        反詰: ['「如果忘記是他們自己選的，為什麼還要殺一個不肯忘記的人？」', '「三十人被排除在大赦外面。那表示連發誓的人自己都知道，有些事不能忘。」', '「你說要讓仇恨停在這一代。那死去的人呢？他們也要停在這一代嗎？」'],
