        引證: ['「三千年後的王表上，沒有他的名字。他們只叫他『那個罪人』。你看，大家都同意了。」', '「新王的石碑上寫著：神廟荒廢，眾神背棄了這片土地。那是誰造成的？」'],
        讓步: ['「……那個石匠刻碑的時候，在唱歌。我記得。」'],
